# CASO-LIM-014 · validate 1d float64
# Bug a corregir: no valida ndim/dtype
import numpy as np

def validate(a):
    print("ok", a.size)

validate(np.array([0.1, 0.2], dtype=np.float64))
try:
    validate(np.array([1, 2]))  # 1D pero no float64
except ValueError as e:
